// Fail-closed auth: reject unless ?t= matches VIO_WEBHOOK_TOKEN. No env set = reject everything.
// Same rule as every other VIO inbound webhook. This one spends real Sendr quota and publishes a
// public page URL, so an open endpoint here is a resource-abuse hole, not just a data leak.
const expected = $env.VIO_WEBHOOK_TOKEN;
const item = $input.item.json;
const q = item.query || {};
const headers = item.headers || {};
const got = q.t || q.token || headers['x-vio-token'];
if (!expected) throw new Error('REFUSED: VIO_WEBHOOK_TOKEN not set (fail-closed)');
if (!got || String(got) !== String(expected)) throw new Error('REFUSED: bad or missing token');
return { json: item.body || item };

// product -> Sendr page template + LinkedIn campaign, plus the campaign copy the page templates
// declare as variables (signal / offer / cta).
//
// GENERATED from reach-engine/config-<product>.json by n8n-workflows/sync-routes.py.
// Do not hand-edit: change the config, then run `python3 sync-routes.py --fix` and re-import.
// Without this, the page silently falls back to whatever placeholder was typed into Sendr and the
// page and the email argue different cases for the same prospect (seen live 2026-08-16).
//
// Fail closed on an unknown product: generating the WRONG product's page for a lead is worse than
// generating none, because it looks deliberate and it is the thing they will actually read.
const ROUTES = {
  oryoniq: {
    product: "OryonIQ",
    template_id: 8462,
    template_name: "OryonIQ - GovCon Capture Page",
    campaign_id: 10748,
    gif_source: "dynamic-website",
    gif_hyperlink_text: "See the 3 pursuits OryonIQ is tracking for your NAICS codes",
    one_liner: "AI market intelligence for GovCon \u2014 surfaces federal pursuits before the RFP.",
    signal: "The Pentagon suspended CMMC Phase II on July 13, 2026, and DoD committed $32B to AI, cloud, and cyber in H1 FY2026 \u2014 federal set-asides are opening fast.",
    offer: "OryonIQ flags the pursuits that fit your NAICS and SDB status before the RFP drops, so you're bidding while everyone else is still searching.",
    cta: "https://www.oryoniq.com/contact",
    booking_url: "",
  },
  visioneerit: {
    product: "VisioneerIT",
    template_id: 8464,
    template_name: "VisioneerIT - Zero-Trust Readiness Page",
    campaign_id: 10751,
    gif_source: "dynamic-website",
    gif_hyperlink_text: "See your agency's zero-trust readiness gaps",
    one_liner: "AI automation, cybersecurity, and digital modernization for federal & SLED agencies.",
    signal: "The Pentagon suspended CMMC Phase II on July 13, 2026, and agencies are under new zero-trust and AI-procurement mandates \u2014 security and modernization budgets are moving now.",
    offer: "VisioneerIT stands up zero-trust, CMMC readiness, and AI-augmented security operations without a year-long procurement cycle.",
    cta: "https://www.visioneerit.com/contact",
    booking_url: "",
  },
};

const lead = $input.item.json;
const key = String(lead.product || '').toLowerCase().replace(/[^a-z]/g, '');
const route = ROUTES[key];

if (!route) {
  return { json: {
    ok: false,
    error: `unknown product "${lead.product}" — expected one of: ${Object.keys(ROUTES).join(', ')}`,
    lead,
  } };
}
if (!lead.first_name || !lead.company) {
  return { json: {
    ok: false,
    error: 'lead needs at least first_name and company — a page with blank merge tags is worse than no page',
    lead,
  } };
}
return { json: { ok: true, ...route, lead } };

// Assemble the exact POST body. Mirrors reach-engine/push_to_sendr_page.py's build_body() —
// same field names, same fallbacks, same degradation rule. Keep the two in sync.
const route = $('Route Product to Template').first().json;
const lead = route.lead;
const templateVars = $input.all().map(i => i.json).filter(v => v && v.tag);

// Map our lead fields onto whatever tags the template actually declares.
const pool = {
  // Per-lead
  first_name: lead.first_name, firstname: lead.first_name,
  company: lead.company, company_name: lead.company,
  title: lead.title, job_title: lead.title,
  company_domain: lead.company_domain,
  opener: lead.opener, personalization: lead.opener,
  // Campaign-level, from the route above. Mirrors push_to_sendr_page.py's pool so the Python and
  // n8n legs fill identical values — anything missing here silently degrades to the placeholder
  // typed into the Sendr template, which is how the two legs drift apart.
  product: route.product, one_liner: route.one_liner,
  signal: route.signal, offer: route.offer, cta: route.cta,
  // Distinct from cta: Sendr's calendar element iframes this. An ordinary page that
  // sets X-Frame-Options renders as a grey broken box (both templates, 2026-08-16).
  booking_url: route.booking_url,
};
const variablesValues = {};
for (const v of templateVars) {
  variablesValues[v.tag] = pool[v.tag] || v.fallback || v.exampleValue || '';
}

// The lead's own site, for the dynamic-website GIF and the video background.
let domain = String(lead.company_domain || '').trim();
if (!domain) {
  const email = String(lead.contact_email || '');
  domain = email.includes('@') ? email.split('@')[1] : '';
}
domain = domain.replace(/^https?:\/\//, '').replace(/\/+$/, '').split('/')[0];
const site = (domain && domain.includes('.')) ? `https://${domain}` : null;

// gifSource is sent EXPLICITLY, never inherited from the template. A template whose GIF element is
// set to dynamic-website or linkedin-profile makes the API reject the whole request with
// "gifWebsiteUrl is required when gifSource is dynamic-website or linkedin-profile" unless a URL
// comes with it (hit live 2026-08-10). Deciding here means a lead with no known domain degrades to
// landing-page — which needs no external URL — instead of failing outright.
const NEEDS_URL = ['dynamic-website', 'linkedin-profile'];
const want = route.gif_source || 'landing-page';
const gifSource = (!NEEDS_URL.includes(want) || site) ? want : 'landing-page';

const body = {
  templateId: route.template_id,
  variablesValues,
  gifSource,
  // Echoed back on every engagement webhook — this is the ONLY thing that lets VIO-sendr-events
  // turn an anonymous "page 123 was viewed" into "Pratik at VisioneerIT opened his page".
  // camelCase deliberately: Sendr camelCases these on the way back (verified live), so sending
  // camelCase keeps sent == received.
  attributes: {
    product: route.product,
    leadEmail: lead.contact_email || '',
    leadName: lead.first_name || '',
    company: lead.company || '',
    apolloId: String(lead.apollo_id || ''),
    sendrCampaignId: String(route.campaign_id || ''),
    source: 'n8n:VIO-sendr-generate-page',
  },
};
if (NEEDS_URL.includes(gifSource)) body.gifWebsiteUrl = site;
if (route.gif_hyperlink_text) body.gifHyperlinkText = route.gif_hyperlink_text;
if (site) { body.videoBackgroundUrl = site; body.videoBackgroundType = 'scroll'; }

return [{ json: { body, degraded: gifSource !== want, site, route_product: route.product,
                  template_id: route.template_id, template_name: route.template_name } }];

// What the caller gets back. pageUrl is the payload — it goes into Instantly's
// {{personalization}} merge tag, or into the Sendr LinkedIn message, before anything is queued.
const built = $('Build Page Request').first().json;
const res = $input.first().json;
return [{ json: {
  ok: true,
  pageUrl: res.pageUrl || null,
  pageId: res.pageId || null,
  previewUrl: res.pagePreviewUrl || null,
  product: built.route_product,
  template: `${built.template_id} · ${built.template_name}`,
  variablesUsed: res.variablesUsed || null,
  gif_degraded_to_landing_page: built.degraded,
  lead_site_used: built.site,
  warnings: res.warnings || [],
  note: 'Page generated only. Nothing sent, nobody enrolled. Assets render async — watch VIO-sendr-events for page:done.',
} }];

// Unroutable input never reaches Sendr. Returned to the caller so the failure is visible where
// it was triggered, rather than being swallowed as a silent no-op.
const j = $input.item.json;
return { json: { ok: false, error: j.error, lead: j.lead,
                 note: 'Nothing was generated and no Sendr quota was spent.' } };
